    [10637]={name="Brewer's Gloves",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Sample for Helbrim'. Pick it over the other reward choices.",zone="Undercity",questName="Sample for Helbrim",lore="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."},
    [10659]={name="Shard of the Splithooves",quality=2,ilvl=57,sourceType="quest_reward",instructions="Reward from the quest 'Heroes of Old'.",zone="Blasted Lands",questName="Heroes of Old",lore="Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."},
    [10751]={name="Gemburst Circlet",quality=3,ilvl=54,sourceType="quest_reward",instructions="Reward from the quest 'The God Hakkar'. Pick it over the other reward choices.",zone="Sunken Temple",questName="The God Hakkar",lore="Now it is time to capture the essence of the avatar of Hakkar. Take the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth."},
    [10820]={name="Jackseed Belt",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Mura Runetotem'. Pick it over the other reward choices.",zone="The Barrens",questName="Mura Runetotem",lore="My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."},
