    [10826]={name="Staff of Lore",quality=2,ilvl=48,sourceType="quest_reward",instructions="Reward from the quest 'Gahz'ridian'. Pick it over the other reward choices.",zone="Tanaris",questName="Gahz'ridian",lore="I'm a scientist, but also a treasure hunter at heart! Long ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity."},
