    [21185]={name="Earthcalm Orb",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
